    <main>
      <section class="support-card" aria-labelledby="support-heading">
        <div class="card-header">
          <p class="eyebrow">Support</p>
          <h1 id="support-heading">How can we help?</h1>
          <p class="intro">
            Tell us where to reach you and our support team will follow up as soon as possible.
          </p>
        </div>

        <form id="contact-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
              aria-invalid="false"
            >
            <p class="error-message" id="full-name-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              required
              aria-describedby="email-error"
              aria-invalid="false"
            >
            <p class="error-message" id="email-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number <span class="helper-text">(optional)</span></label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-help phone-error"
              aria-invalid="false"
              placeholder="555-123-4567"
            >
            <p class="helper-text" id="phone-help">Expected format: 555-123-4567.</p>
            <p class="error-message" id="phone-error" aria-live="polite"></p>
          </div>

          <button type="submit">Submit support request</button>
          <p class="success-message" id="success-message" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#contact-form");
      const successMessage = document.querySelector("#success-message");

      const fields = {
        fullName: {
          input: document.querySelector("#full-name"),
          error: document.querySelector("#full-name-error"),
          validate(value) {
            return value.trim() ? "" : "Enter your full name.";
          },
        },
        email: {
          input: document.querySelector("#email"),
          error: document.querySelector("#email-error"),
          validate(value) {
            const trimmedValue = value.trim();
            if (!trimmedValue) {
              return "Enter your email address.";
            }

            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)
              ? ""
              : "Enter a valid email address, such as name@example.com.";
          },
        },
        phone: {
          input: document.querySelector("#phone"),
          error: document.querySelector("#phone-error"),
          validate(value) {
            const trimmedValue = value.trim();
            if (!trimmedValue) {
              return "";
            }

            return /^\d{3}-\d{3}-\d{4}$/.test(trimmedValue)
              ? ""
              : "Enter a phone number in the format 555-123-4567.";
          },
        },
      };

      function setFieldError(field, message) {
        field.error.textContent = message;
        field.input.setAttribute("aria-invalid", message ? "true" : "false");
      }

      function validateField(field) {
        const message = field.validate(field.input.value);
        setFieldError(field, message);
        return !message;
      }

      Object.values(fields).forEach((field) => {
        field.input.addEventListener("blur", () => {
          validateField(field);
        });

        field.input.addEventListener("input", () => {
          if (field.input.getAttribute("aria-invalid") === "true") {
            validateField(field);
          }
          successMessage.textContent = "";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        successMessage.textContent = "";

        const firstInvalidField = Object.values(fields).find((field) => !validateField(field));

        if (firstInvalidField) {
          firstInvalidField.input.focus();
          return;
        }

        form.reset();
        Object.values(fields).forEach((field) => setFieldError(field, ""));
        successMessage.textContent = "Thanks. Your support request is ready to send.";
      });
    </script>
  </body>
